import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-03-10 :: Ceph Crimson Meeting","description":"","frontmatter":{"title":"2020-03-10 :: Ceph Crimson Meeting","date":"2020-03-10T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","会议纪要","分布式存储","代码审查","性能优化","事务处理","状态图","内存管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-10_-_-_Ceph_Crimson_Meeting.md","filePath":"posts/2020/2020-03-10_-_-_Ceph_Crimson_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-03-10_-_-_Ceph_Crimson_Meeting.md"};function r(n,l,s,h,u,p){return e(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间与参与人员" tabindex="-1">会议时间与参与人员 <a class="header-anchor" href="#会议时间与参与人员" aria-label="Permalink to &quot;会议时间与参与人员&quot;">​</a></h4><ul><li><strong>时间：</strong> 美国东部时间早上7点。</li><li><strong>参与人员：</strong> 多位研发人员参与了Ceph分布式存储系统的讨论。</li></ul><h4 id="主要讨论议题" tabindex="-1">主要讨论议题 <a class="header-anchor" href="#主要讨论议题" aria-label="Permalink to &quot;主要讨论议题&quot;">​</a></h4><ol><li><p><strong>代码审查与学习</strong></p><ul><li>一位成员正在学习Sam和其他成员合作编写的代码，特别是在某些服务上的工作。</li><li>成员计划详细审查下载到个人笔记本电脑的代码。</li></ul></li><li><p><strong>系统改进与跟踪路径</strong></p><ul><li>讨论了在处理叶节点时跟踪路径的需求，以便在不返回的情况下合并父节点。</li><li>提交了SMP更改以辅助讨论组，移除某些条件。</li></ul></li><li><p><strong>性能问题与代码修复</strong></p><ul><li>讨论了性能回归问题，特别是与USD性能相关的问题。</li><li>一位成员反向修复了一些补丁，但发现对性能没有显著影响。</li></ul></li><li><p><strong>事务处理与代码理解</strong></p><ul><li>讨论了事务处理的相关问题，特别是对象启动事务与块级事务的区别。</li><li>一位成员正在编写状态图，以更好地理解代码逻辑。</li></ul></li><li><p><strong>代码调试与环境设置</strong></p><ul><li>一位成员正在调试PG log base 2恢复代码，并发现了一些需要先修复的其他问题。</li><li>成员还设置了Alien Store环境，计划进行FIO测试。</li></ul></li><li><p><strong>接口与内存管理</strong></p><ul><li>讨论了连接关闭接口的修改，以避免死锁问题。</li><li>探讨了Google的内存管理技巧，以及如何在Ceph中应用这些技巧。</li></ul></li><li><p><strong>索引与性能优化</strong></p><ul><li>讨论了如何在Ceph中有效地构建H对象的索引，特别是在处理变长键时。</li><li>提出了使用前缀压缩和其他编码技巧来优化性能。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>需要进一步研究和实验以解决性能回归问题。</li><li>需要对事务处理和状态图进行更深入的理解和文档化。</li><li>需要继续调试和修复PG log base 2恢复代码中的问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续审查和学习相关代码，确保对系统有深入的理解。</li><li>完成状态图的编写，并将其作为文档分享给团队。</li><li>继续进行FIO测试和环境设置，以支持后续的调试工作。</li><li>继续研究和实验，以找到有效的索引和性能优化方法。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>确认会议录音是否需要上传到YouTube，并安排相关人员负责。</li><li>强调在新代码中包含函数头注释的重要性，以提高代码的可读性和维护性。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，计划下周再次进行会议。</li></ul><p>在本次会议中，Ceph团队深入讨论了代码审查、系统改进、性能优化、事务处理、代码调试、接口与内存管理、索引与性能优化等多个方面，并制定了后续的行动计划。</p>',14)])])}const g=i(o,[["render",r]]);export{d as __pageData,g as default};
